#!/bin/bash
#
# What a call yields follows Perl: it depends on the form of the `return`
# that ran and on the caller's context.
#
#   forms.strada     20 return forms, 10 methods, closures, a code reference
#                    and a dynamic method name, each read in 11 contexts
#                    (list item, my @a =, my ($x, $y) =, foreach, variadic
#                    and method arguments, [...], push, my $n =, an element
#                    store, if), twice over (the answer must not depend on
#                    what ran before). Generated by gen_forms.py.
#   contexts.strada  further contexts: sort/map/grep/reverse input, hash
#                    initializers, { ... }, concatenation, arithmetic,
#                    scalar(), defined, bare `return;` against
#                    `return undef;`, closures, wantarray, list slices.
#
# NAME.pl is the same program in Perl; NAME.expected is its output from
# Perl 5.38. Each NAME.strada must print exactly that, compiled and in the
# VM with the JIT on and off. With perl on the PATH the expected files are
# also checked against a fresh run of the .pl files.
#
# Exits non-zero on any failure.

set -u
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_DIR="$(cd "$SCRIPT_DIR/../.." && pwd)"
STRADA="$REPO_DIR/strada"
INTERP="$REPO_DIR/interpreter/strada-interp"
if [ ! -x "$STRADA" ]; then
    echo "Build strada first (run 'make' in $REPO_DIR)" >&2
    exit 2
fi
WORK="$(mktemp -d)"
trap 'rm -rf "$WORK"' EXIT
fail=0

check() {
    local what="$1" got="$2" want="$3"
    if diff "$want" "$got" > "$WORK/diff.txt" 2>&1; then
        echo "ok - $what"
    else
        echo "not ok - $what"
        head -20 "$WORK/diff.txt"
        fail=1
    fi
}

for name in forms contexts; do
    want="$SCRIPT_DIR/$name.expected"
    if command -v perl > /dev/null 2>&1; then
        perl "$SCRIPT_DIR/$name.pl" > "$WORK/$name.perl" 2> /dev/null
        check "$name: expected file is what perl prints" "$WORK/$name.perl" "$want"
    fi
    if "$STRADA" -o "$WORK/$name.bin" "$SCRIPT_DIR/$name.strada" > "$WORK/$name.build" 2>&1; then
        "$WORK/$name.bin" > "$WORK/$name.c.out" 2>&1
        check "$name (compiled)" "$WORK/$name.c.out" "$want"
    else
        echo "not ok - $name (compiled): build failed"
        head -10 "$WORK/$name.build"
        fail=1
    fi
    if [ -x "$INTERP" ]; then
        "$INTERP" "$SCRIPT_DIR/$name.strada" > "$WORK/$name.v.out" 2>&1
        check "$name (VM)" "$WORK/$name.v.out" "$want"
        "$INTERP" --no-jit "$SCRIPT_DIR/$name.strada" > "$WORK/$name.n.out" 2>&1
        check "$name (VM, no JIT)" "$WORK/$name.n.out" "$want"
    fi
done
exit $fail
